(function(){
const STORAGE='student_os_local_v1';
function toast(msg){const x=document.createElement('div');x.className='os-toast';x.textContent=msg;document.body.appendChild(x);setTimeout(()=>x.remove(),2800)}
function close(){document.querySelector('.os-overlay')?.remove()}
function modal(body){close();const o=document.createElement('div');o.className='os-overlay';o.innerHTML='<div class="os-dialog">'+body+'</div>';o.addEventListener('click',e=>{if(e.target===o)close()});document.body.appendChild(o);return o}
function intro(){if(localStorage.getItem(STORAGE))return;modal('<div class="os-kicker">Student OS · البداية السريعة</div><h2>أهلًا بك في مساحتك الدراسية</h2><p>Student OS لا يطلب منك أن تتعلم نظامًا معقدًا. فقط أخبره بموادك وامتحاناتك ووقتك، وهو يوضح لك ماذا تذاكر الآن.</p><div class="os-walk"><div><b>خطط</b><span>خطة يومية مبنية على امتحاناتك وأولوياتك.</span></div><div><b>ركّز</b><span>ابدأ جلسة واضحة بمؤقت وقائمة صغيرة.</span></div><div><b>تكيّف</b><span>إذا تأخرت، يعيد توزيع اليوم بدل أن يعاقبك.</span></div></div><div class="os-actions"><button class="os-primary" data-os="setup">ابدأ إعداد فصلي الدراسي ←</button><button class="os-secondary" data-os="demo">استخدم البيانات التجريبية</button></div>')}
function setup(){modal('<div class="os-kicker">إعداد الفصل · 1 من 3</div><h2>لنجهز خطتك الأولى</h2><p>هذه البيانات تحفظ محليًا على جهازك الآن. يمكن ربطها بحساب حقيقي لاحقًا.</p><label>اسمك</label><input class="os-field" id="os-name" placeholder="مثال: سيف"><label>التخصص</label><input class="os-field" id="os-major" placeholder="مثال: حماية النبات"><label>كم ساعة تستطيع المذاكرة يوميًا؟</label><div class="os-choice"><button data-hours="2">ساعتان</button><button data-hours="3" class="selected">3 ساعات</button><button data-hours="4">4 ساعات</button><button data-hours="5">5+</button></div><div class="os-actions"><button class="os-primary" data-os="setup2">متابعة ←</button></div>')}
function setup2(){modal('<div class="os-kicker">إعداد الفصل · 2 من 3</div><h2>أضف موادك</h2><p>ابدأ بمادتين أو ثلاث. يمكنك إضافة المزيد من داخل لوحة التحكم.</p><input class="os-field" id="os-course1" placeholder="المادة الأولى" value="الإحصاء"><input class="os-field" id="os-course2" placeholder="المادة الثانية" value="التصنيف"><input class="os-field" id="os-course3" placeholder="المادة الثالثة" value="أمراض النبات"><div class="os-actions"><button class="os-primary" data-os="setup3">متابعة ←</button></div>')}
function setup3(){modal('<div class="os-kicker">إعداد الفصل · 3 من 3</div><h2>متى أقرب امتحان؟</h2><p>لا تحتاج أن تكون دقيقًا جدًا الآن. سنبني لك أول خطة ويمكنك تعديلها لاحقًا.</p><label>المادة الأهم</label><select class="os-field"><option>الإحصاء</option><option>التصنيف</option><option>أمراض النبات</option></select><label>موعد الامتحان</label><input class="os-field" type="date" value="2026-09-11"><div class="os-actions"><button class="os-primary" data-os="finishsetup">أنشئ خطتي الأولى ←</button></div>')}
function finish(){localStorage.setItem(STORAGE,JSON.stringify({ready:true,createdAt:new Date().toISOString()}));close();toast('تم إنشاء خطتك الأولى. ابدأ من الأولوية اليومية.');}
function recovery(){modal('<div class="os-kicker">وضع الاستعادة</div><h2>ولا يهم أنك تأخرت</h2><p>سنعيد توزيع الجلسات ونحمي المواد ذات الأولوية. اختر الحل الأقرب لطاقتك اليوم.</p><div class="os-choice"><button class="selected">انقل جلسة للغد</button><button>مدد اليوم 40 دقيقة</button><button>قلل المراجعة الأقل أولوية</button></div><div class="os-actions"><button class="os-primary" data-os="apply">تطبيق الخطة الجديدة</button><button class="os-secondary" data-os="close">إلغاء</button></div>')}
function focus(){let sec=45*60,paused=false;const o=modal('<div class="os-kicker">جلسة تركيز · الإحصاء</div><h2>الاحتمالات والتوزيعات</h2><p>هدف الجلسة: فهم الفكرة الأساسية وحل تمرين واحد.</p><div class="os-timer" id="os-clock">45:00</div><div class="os-choice"><button>□ اقرأ</button><button>□ افهم</button><button>□ تدرّب</button></div><div class="os-actions"><button class="os-secondary" data-os="pause">إيقاف مؤقت</button><button class="os-primary" data-os="finishfocus">إنهاء الجلسة</button></div>');const int=setInterval(()=>{if(!paused&&sec>0){sec--;const e=document.getElementById('os-clock');if(e)e.textContent=Math.floor(sec/60)+':'+String(sec%60).padStart(2,'0')}},1000);o.dataset.timer='1';o.addEventListener('click',e=>{if(e.target.dataset.os==='pause'){paused=!paused;e.target.textContent=paused?'استئناف':'إيقاف مؤقت'}if(e.target.dataset.os==='finishfocus'){clearInterval(int);close();toast('أحسنت. تم تسجيل الجلسة وتحديث تقدم المادة.')}})}
document.addEventListener('click',function(e){const t=e.target.closest('[data-os]');if(!t)return;const a=t.dataset.os;if(a==='setup')setup();else if(a==='setup2')setup2();else if(a==='setup3')setup3();else if(a==='finishsetup')finish();else if(a==='demo'){localStorage.setItem(STORAGE,'demo');close();toast('تم تفعيل البيانات التجريبية. ابدأ من بطاقة الأولوية.')}else if(a==='recovery')recovery();else if(a==='apply'){close();toast('تمت إعادة بناء خطتك ونقل الجلسة الأقل أولوية.')}else if(a==='focus')focus();else if(a==='close')close()},{capture:true});
document.addEventListener('click',function(e){const text=(e.target.innerText||'').trim();if(text.includes('أنا متأخر اليوم')){e.stopImmediatePropagation();recovery()}else if(text.includes('ابدأ الجلسة المقترحة')||text==='ابدأ'){e.stopImmediatePropagation();focus()}},{capture:true});
window.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();modal('<div class="os-kicker">اختصار سريع</div><h2>ماذا تريد أن تفعل؟</h2><input class="os-field" autofocus placeholder="ابحث عن مادة أو مهمة أو صفحة..."><p class="muted">جرّب: الإحصاء، جلسة التركيز، الامتحانات، المهام</p>')}});
setTimeout(intro,500);
})();

(function(){
const SUPABASE_URL='https://ksttmtdlihiqhvlvisoh.supabase.co';
const SUPABASE_ANON_KEY='eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzIiwicmVmIjoia3N0dG10ZGxpaGlxbHZsaXNvaCIsInJvbGUiOiJhbm9uIiwiaWF0IjoxNzg4NzQyNTY1LCJleHAiOjIxMDQzMTg1Nn0.7XLPoF8r3BAjKC5vcIIQhR7ohxrQCaV079Xm6tr_El4';
const AUTH=SUPABASE_URL+'/auth/v1';const TOKEN_KEY='student_os_supabase_session';
let session=null;try{session=JSON.parse(localStorage.getItem(TOKEN_KEY)||'null')}catch(e){}
function headers(token){return {'apikey':SUPABASE_ANON_KEY,'Content-Type':'application/json',...(token?{Authorization:'Bearer '+token}:{})}}
async function auth(path,body,token){const r=await fetch(AUTH+path,{method:(path==='/user'&&body)?'PUT':(body?'POST':'GET'),headers:headers(token),body:body?JSON.stringify(body):undefined});const d=await r.json().catch(()=>({}));if(!r.ok)throw Error(d.error_description||d.msg||d.message||'حدث خطأ في الاتصال');return d}
function accountButton(){let b=document.querySelector('.cloud-account');if(!b){b=document.createElement('button');b.className='cloud-account';document.body.appendChild(b);b.onclick=()=>session?accountModal():loginModal()}b.textContent=session?(session.user?.email||'حسابي'):'تسجيل الدخول';b.classList.toggle('online',!!session)}
function overlay(html){document.querySelector('.cloud-auth')?.remove();const o=document.createElement('div');o.className='os-overlay cloud-auth';o.innerHTML='<div class="os-dialog">'+html+'</div>';o.onclick=e=>{if(e.target===o)o.remove()};document.body.appendChild(o);return o}
function loginModal(mode='login'){const signup=mode==='signup';const o=overlay('<div class="os-kicker">Student OS · الحساب</div><h2>'+ (signup?'إنشاء حساب طالب':'تسجيل الدخول')+'</h2><p>'+(signup?'احفظ خطتك وبياناتك لتصل إليها من أي جهاز.':'ادخل إلى مساحة مذاكرتك المحفوظة.')+'</p><label>البريد الإلكتروني</label><input id="cloud-email" type="email" placeholder="you@example.com"><label>كلمة المرور</label><input id="cloud-password" type="password" placeholder="6 أحرف على الأقل"><div class="os-actions"><button class="os-primary" data-cloud="submit">'+(signup?'إنشاء الحساب':'دخول')+'</button><button class="os-secondary" data-cloud="switch">'+(signup?'لدي حساب بالفعل':'إنشاء حساب جديد')+'</button></div><div id="cloud-message"></div>');o.addEventListener('click',async e=>{const a=e.target.dataset.cloud;if(a==='switch'){loginModal(signup?'login':'signup');return}if(a==='submit'){const email=o.querySelector('#cloud-email').value.trim(),password=o.querySelector('#cloud-password').value;const msg=o.querySelector('#cloud-message');if(!email||password.length<6){msg.className='cloud-error';msg.textContent='اكتب بريدًا صحيحًا وكلمة مرور من 6 أحرف على الأقل.';return}e.target.disabled=true;try{const d=await auth(signup?'/signup':'/token?grant_type=password',{email,password});session=d;localStorage.setItem(TOKEN_KEY,JSON.stringify(d));msg.className='cloud-success';msg.textContent=signup?'تم إنشاء الحساب. افحص بريدك إذا طلب Supabase التأكيد.':'تم تسجيل الدخول بنجاح.';accountButton();setTimeout(()=>o.remove(),800)}catch(err){msg.className='cloud-error';msg.textContent=err.message;e.target.disabled=false}}})}
function accountModal(){const email=session?.user?.email||'';const o=overlay('<div class="os-kicker">Student OS · الحساب السحابي</div><h2>حسابك متصل</h2><p>'+email+'</p><div class="os-actions"><button class="os-primary" data-cloud="sync">حفظ بيانات التجربة</button><button class="os-secondary" data-cloud="logout">تسجيل الخروج</button></div><div id="cloud-message"></div>');o.addEventListener('click',async e=>{const msg=o.querySelector('#cloud-message');if(e.target.dataset.cloud==='logout'){await fetch(AUTH+'/logout',{method:'POST',headers:headers(session.access_token)}).catch(()=>{});session=null;localStorage.removeItem(TOKEN_KEY);accountButton();o.remove();return}if(e.target.dataset.cloud==='sync'){try{const local={name:'سيف',courses:['الإحصاء','التصنيف','أمراض النبات'],updatedAt:new Date().toISOString()};const d=await auth('/user',{data:{student_os:local}},session.access_token);session.user=d;localStorage.setItem(TOKEN_KEY,JSON.stringify(session));msg.className='cloud-success';msg.textContent='تم حفظ بياناتك في حساب Supabase.'}catch(err){msg.className='cloud-error';msg.textContent=err.message}}})}
async function restore(){if(!session?.access_token)return;try{const d=await auth('/user',null,session.access_token);session.user=d;localStorage.setItem(TOKEN_KEY,JSON.stringify(session))}catch(e){session=null;localStorage.removeItem(TOKEN_KEY)}}
window.studentOSCloud={login:loginModal,logout:()=>{session=null;localStorage.removeItem(TOKEN_KEY);accountButton()},getSession:()=>session};
setTimeout(async()=>{await restore();accountButton()},700);
})();
